/**
 * Sample Pulse recordings placed in every demonstration district, so that its CRP has recordings
 * to listen to. Each is an adult reading one of the application's passages the way a child of the
 * grade reads it, scored by the engine itself; the score stored with it is the engine's own output
 * for that file. The audio is kept here, encoded, so that it is deployed with the function.
 */

export interface DemoRecording {
  key: string;
  type: 'audio/webm' | 'audio/ogg' | 'audio/mp4';
  grade: 1 | 2 | 3;
  itemCode: string;
  promptCode: string;
  durationMs: number;
  bytes: number;
  /** What the teacher recorded on the form. */
  teacherReading: 'fluent' | 'hesitant' | 'needs_support';
  teacherEnglish: 'sentences' | 'words' | 'no_response';
  /** When the screen changed level during the recording. */
  shown: { level: string; atMs: number }[];
  /** The engine's score of the file, as `pulse_scores` holds it. */
  score: Record<string, unknown>;
}

