/** The files, Opus in WebM at 32 kbit/s, as a phone records them in the application. */
const AUDIO: Readonly<Record<string, string>> = {
  'class-2-crow':
    '',
  'class-2-meera':
    '',
  'class-3-lion':
    '',
  'class-3-diwali':
    '',
};

/** The file of a recording. */
export function recordingBytes(key: string): Uint8Array {
  const encoded = AUDIO[key];
  if (encoded === undefined) {
    throw new Error(`There is no recording "${key}".`);
  }
  const binary = atob(encoded);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}
